class StreamingRequirement {
    final String name;
    final boolean needsKafkaCompatibility;  // existing Kafka clients/connectors
    final boolean needsPortability;          // move across clouds / on-prem
    final boolean needsKafkaEcosystem;       // Kafka Connect / Streams
    final boolean prioritizesAwsSimplicity;  // least ops + deep AWS integration

    StreamingRequirement(String name, boolean kafkaCompat, boolean portability,
                         boolean kafkaEcosystem, boolean awsSimplicity) {
        this.name = name;
        this.needsKafkaCompatibility = kafkaCompat;
        this.needsPortability = portability;
        this.needsKafkaEcosystem = kafkaEcosystem;
        this.prioritizesAwsSimplicity = awsSimplicity;
    }
}
