package com.bank.stream.choice;

// A streaming backbone and the traits it offers.
interface StreamingBackbone {
    String name();
    boolean kafkaCompatible();
    boolean portable();
    boolean kafkaEcosystem();
    boolean awsNativeSimplicity();

    // Score how well this backbone fits a requirement (higher is better).
    default int fitScore(StreamingRequirement r) {
        int score = 0;
        if (r.needsKafkaCompatibility && kafkaCompatible()) score += 2;
        if (r.needsPortability && portable()) score += 2;
        if (r.needsKafkaEcosystem && kafkaEcosystem()) score += 2;
        if (r.prioritizesAwsSimplicity && awsNativeSimplicity()) score += 2;
        return score;
    }
}
