package com.bank.stream.choice;

import java.util.logging.Logger;

// Recommends the higher-scoring backbone for a requirement, with reasoning.
class BackboneSelector {
    private static final Logger log = Logger.getLogger(BackboneSelector.class.getName());

    private final MskBackbone msk = new MskBackbone();
    private final KinesisBackbone kinesis = new KinesisBackbone();

    StreamingBackbone recommend(StreamingRequirement r) {
        int mskScore = msk.fitScore(r);
        int kinScore = kinesis.fitScore(r);
        StreamingBackbone chosen = mskScore >= kinScore ? msk : kinesis;
        log.info(() -> "'" + r.name + "' msk=" + mskScore + " kinesis=" + kinScore
                + " -> " + chosen.name());
        return chosen;
    }
}
