package com.bank.stream.choice;

import java.util.logging.ConsoleHandler;
import java.util.logging.Formatter;
import java.util.logging.Level;
import java.util.logging.LogRecord;
import java.util.logging.Logger;

public class MskVsKinesisDemo {
    private static final Logger log = Logger.getLogger(MskVsKinesisDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new BankLogFormatter());
        handler.setLevel(Level.ALL);
        root.addHandler(handler);
        root.setLevel(Level.INFO);
    }

    public static void main(String[] args) {
        BackboneSelector selector = new BackboneSelector();

        // Existing on-prem Kafka backbone migrating to cloud (needs Kafka + portability).
        StreamingRequirement coreBackbone = new StreamingRequirement(
                "core-txn-backbone", true, true, true, false);

        // New AWS-native analytics project (wants simplicity + deep AWS integration).
        StreamingRequirement awsAnalytics = new StreamingRequirement(
                "new-aws-analytics", false, false, false, true);

        StreamingBackbone r1 = selector.recommend(coreBackbone);
        log.info("RECOMMEND core-txn-backbone => " + r1.name());

        StreamingBackbone r2 = selector.recommend(awsAnalytics);
        log.info("RECOMMEND new-aws-analytics => " + r2.name());
    }
}

